import sys
import random

def solution(input_data):
    lines = input_data.strip().split('\n')
    idx = 0

    n, e = map(int, lines[idx].split())
    idx += 1

    # Store hate pairs as tuples (min, max)
    hate = set()
    for i in range(e):
        a, b = map(int, lines[idx].split())
        idx += 1
        hate.add(tuple(sorted((a, b))))

    # Parse trainer data
    trainers = []
    for trainer_id in range(1, n + 1):
        line_parts = list(map(int, lines[idx].split()))
        idx += 1
        wish_list = line_parts[1:]  # Skip count
        trainers.append({'id': trainer_id, 'wish_list': wish_list})

    # Find T (max team ID)
    T = 0
    for t in trainers:
        for team in t['wish_list']:
            T = max(T, team)

    # Make sure conferences exist for all teams 1..T
    def count_hate(team_assignment, conferences, T):
        total = 0
        for a in range(1, n + 1):
            ta = team_assignment.get(a)
            if ta and ta <= T:
                conf_a = conferences.get(ta, 1)
                for b in range(a + 1, n + 1):
                    if (a, b) in hate:
                        tb = team_assignment.get(b)
                        if tb and tb <= T and tb != ta:
                            conf_b = conferences.get(tb, 1)
                            if conf_a != conf_b:
                                total += 1
        return total

    def get_conference_for(aggr_teams):
        result = {}
        for team in range(1, T + 1):
            if team not in aggr_teams:
                result[team] = random.choice([1, 2])
            else:
                result[team] = aggr_teams[team]
        return result

    best_result = None
    best_hate = -1
    best_num = -1

    for trial in range(500):
        # Random initial assignment
        team_assignment = {}
        for t in trainers:
            team_assignment[t['id']] = random.choice(t['wish_list'])

        # Random conference assignment
        conferences = {}
        for team in range(1, T + 1):
            conferences[team] = random.choice([1, 2])

        # Local search
        current_hate = count_hate(team_assignment, conferences, T)

        for _ in range(50):
            improvements = 0
            improved_something = False

            for team in range(1, T + 1):
                old_conf = conferences[team]
                new_conf = 3 - old_conf

                # Count hate pairs involving this team's trainers
                involve_conf_a = 0
                involve_diff = 0
                for a in range(1, n + 1):
                    if team_assignment[a] == team:
                        for b in range(a + 1, n + 1):
                            if (a, b) in hate:
                                tb = team_assignment.get(b)
                                if tb and tb in conferences:
                                    if conferences[tb] != old_conf:
                                        involve_conf_a += 1
                                    if conferences[tb] != new_conf:
                                        involve_diff += 1
                                if tb and tb not in conferences:
                                    if old_conf != 1:
                                        involve_diff += 1
                                    else:
                                        involve_conf_a += 1

                if involve_conf_a > 0 and involve_diff > 0:
                    if involve_conf_a > involve_diff:
                        conferences[team] = new_conf
                        improved_something = True

        current_hate = count_hate(team_assignment, conferences, T)
        if current_hate >= e // 2 and current_hate > best_hate:
            best_hate = current_hate
            best_result = (team_assignment.copy(), conferences.copy())
        if current_hate < best_hate and best_hate > e // 2:
            break

    if best_result:
        assignment, conferences = best_result
        assignment_output = ' '.join(str(assignment[t['id']]) for t in trainers)
        conference_output = ' '.join(str(conferences.get(i, 1)) for i in range(1, T + 1))
        return f"{assignment_output}\n{conference_output}"
    else:
        assignment = team_assignment
        conferences = {}
        for i in range(1, T + 1):
            conferences[i] = 1
        assignment_output = ' '.join(str(assignment[t['id']]) for t in trainers)
        conference_output = ' '.join(str(conferences.get(i, 1)) for i in range(1, T + 1))
        return f"{assignment_output}\n{conference_output}"
