def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    p = list(map(int, lines[2].split()))
    m = int(lines[3])
    b = list(map(int, lines[4].split()))

    # Map first occurrence of each value and store in order needed
    first_occ = {}
    for i in range(n):
        if a[i] not in first_occ:
            first_occ[a[i]] = i

    # Check all elements of b exist in a and occur in order
    last_pos = -1
    for val in b:
        if val not in first_occ:
            return "NO"
        if first_occ[val] <= last_pos:
            return "NO"
        last_pos = first_occ[val]

    # Calculate the cost of mandatory deletions
    ans_cost = 0

    # For b[0]: elements at indices < first_occ[b[0]] with a[idx] >= b[0] must be deleted
    threshold = b[0]
    for i in range(first_occ[threshold]):
        if a[i] >= threshold:
            ans_cost += p[i]

    # For each subsequent element in b: elements between previous b[i] and current b[i]
    # with value >= current b[i] must be deleted
    prev_val = b[0]
    prev_idx = first_occ[prev_val]

    for i in range(1, m):
        curr_val = b[i]
        curr_idx = first_occ[curr_val]

        # Check elements between prev_idx and curr_idx
        for j in range(prev_idx + 1, curr_idx):
            if a[j] >= curr_val:
                ans_cost += p[j]

        prev_val = curr_val
        prev_idx = curr_idx

    return "YES\n{}".format(ans_cost)
