def is_gp(seq):
    """Check if sequence is a geometric progression"""
    n = len(seq)
    if n <= 1:
        return True

    # Handle all zeros case
    if all(x == 0 for x in seq):
        return True

    # First step ratio
    c = seq[0]
    if c == 0:
        # If first is 0, all subsequent must be 0 for GP
        return all(x == 0 for x in seq)

    b = 1
    for i in range(1, n):
        if seq[i] == 0:
            return False
        temp = seq[i] / c
        if b == 0:
            b = temp
        elif seq[i] * b != c * pow(b, i):
            # Check with floating point tolerance
            if abs(seq[i] * b - c * pow(b, i)) > 1e-9:
                return False
        else:
            b = temp
        # Verify ratio consistency
        if i > 1 and seq[i] * b * b != seq[i-2] * b * seq[i-1]:
            return False

    return True
