def solution(input_str):
    lines = input_str.strip().split('\n')
    n, _ = map(int, lines[0].split())
    events = lines[1:]

    segments = []
    current_segment = None

    for event in events:
        parts = event.split()
        if parts[0] == '1':
            if current_segment is not None:
                segments.append(current_segment)
            current_segment = set()
        else:
            current_segment.add(parts[1])

    if current_segment is not None:
        segments.append(current_segment)

    if not segments:
        return 0

    all_friends = set()
    for seg in segments:
        all_friends.update(seg)

    if not all_friends:
        return 0

    friends = sorted(list(all_friends))
    m = len(friends)

    if m == 0:
        return 0

    fri_map = {f: i for i, f in enumerate(friends)}

    friend_seg = [set() for _ in range(m)]
    for i, seg in enumerate(segments):
        for friend in seg:
            if friend in fri_map:
                friend_seg[fri_map[friend]].add(i)

    adj = [[False] * m for _ in range(m)]
    for i in range(m):
        for j in range(i + 1, m):
            if friend_seg[i] & friend_seg[j]:
                adj[i][j] = adj[j][i] = True

    # Maximum Independent Set using branch and bound
    best = [0]

    def solve(mask, count, k):
        if count + len(friends) - k <= best[0]:
            return

        if mask == (1 << m) - 1:
            best[0] = max(best[0], count)
            return

        # Find first unselected vertex
        first = k
        while first < m and ((mask >> first) & 1):
            first += 1

        if first >= m:
            best[0] = max(best[0], count)
            return

        # Branch: include vertex 'first'
        new_mask = mask | (1 << first)
        new_count = count + 1

