def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return '0'

    n = int(lines[0])
    adj = [[] for _ in range(n + 1)]

    for i in range(1, min(n, len(lines)-1)):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)

    if n == 1:
        return '1'

    parent = [0] * (n + 1)
    order = []
    stack = [1]
    visited = [False] * (n + 1)
    visited[1] = True

    while stack:
        u = stack.pop()
        order.append(u)
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                stack.append(v)

    order.reverse()

    # dp[u][s] = max product from subtree u, where component containing u has size s
    dp = [[0.0] * (n + 1) for _ in range(n + 1)]

    for u in order:
        dp[u][1] = 1.0
        sz = 1

        for v in adj[u]:
            if v == parent[u]:
                continue

            for s_u in range(1, sz + 1):
                for s_v in range(1, len(dp[v]) - 1):
                    if dp[v][s_v] < 1e-9 or dp[u][s_u] <= 0:
                        continue

                    # Cut edge (u, v)
                    prod_cut = dp[u][s_u] * s_v

                    # Merge: sizes add up
                    new_size = s_u + s_v
                    prod_merge = dp[u][s_u]  # Product doesn't change, size increases

                    if prod_cut > dp[u][new_size]:
                        dp[u][new_size] = prod_cut
                    if prod_merge > dp[u][new_size]:
                        dp[u][new_size] = prod_merge

            sz += len(adj[u])

    ans = 0
    for s in range(1, n + 1):
        ans = max(ans, int(round(float(dp[1][s]))))

    return str(ans)
