        T[i][i] = 1  # Stay at same island

        for j in range(size):
            if i == j:
                continue
            v = j + 1
            common_divs = bin(u & v).count('1')
            if common_divs > 0:
                T[i][j] = (1 << common_divs) % MOD

    T_exp = matrix_pow(T, t, MOD, size)

    # Compute answer for each island and XOR them
