        for j in range(size):
            xor_sum_col ^= T_exp[j][i]
        result ^= (xor_sum_col * (a[i] % MOD)) % MOD

    return f"{result}\n"


def multiply(A, B, MOD, n):
    C = [[0] * n for _ in range(n)]
    for i in range(n):
        for k in range(n):
            if A[i][k] == 0:
                continue
            for j in range(n):
                C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
    return C


def matrix_pow(A, p, MOD, n):
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        result[i][i] = 1

    while p > 0:
        if p & 1:
            result = multiply(result, A, MOD, n)
        A = multiply(A, A, MOD, n)
        p >>= 1

    return result
