    # The visited_mask tracks which planets in [1, current_pos + m] have been visited

    # Since n can be up to 10^5, we need to be smart about state
    # Key observation: with small m, we only need to track locally

    memo = {}

    def dp(pos, visited_mask, visited_count):
        """Count ways to visit remaining k - visited_count planets starting from pos"""
        if visited_count == k:
