            # If this planet hasn't been visited yet
            if not ((visited_mask >> (next_planet - pos - 1)) & 1):
                new_mask = visited_mask | (1 << (next_planet - pos - 1))
                result = (result + dp(next_planet, new_mask, visited_count + 1)) % MOD

