EX_MOD = MOD - 1

def mat_mul(A, B):
    n = len(A)
    C = [[0] * n for _ in range(n)]
    for i in range(n):
        for k in range(n):
            if A[i][k]:
                for j in range(n):
                    C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % EX_MOD
    return C

def mat_pow(A, p):
    n = len(A)
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        result[i][i] = 1
    while p > 0:
        if p % 2 == 1:
            result = mat_mul(result, A)
        A = mat_mul(A, A)
        p //= 2
    return result

def get_indices(n, init):
    """Computes the exponent for a parameter using matrix exponentiation."""
    if n == 1:
        return init[0] % EX_MOD
    if n == 2:
        return init[1] % EX_MOD
    if n == 3:
        return init[2] % EX_MOD

    M = [[1, 1, 1],
         [1, 0, 0],
         [0, 1, 0]]

    Mn = mat_pow(M, n - 4)

    init = [init[2], init[1], init[0]]

    result = (Mn[0][0] * init[0] + Mn[0][1] * init[1] + Mn[0][2] * init[2]) % EX_MOD
    return result

