        farthest = max(range(1, n + 1), key=lambda x: dist1[x])
        dist2 = bfs(farthest)
        farthest2 = max(range(1, n + 1), key=lambda x: dist2[x])
        diameter = dist2[farthest2]
        return farthest, farthest2, dist2

    # LCA using binary lifting
    LOG = max(14, n.bit_length())
    parent = [[0] * (n + 1) for _ in range(LOG)]
    depth = [-1] * (n + 1)

    def dfs_lca(root, p, d):
        depth[root] = d
        parent[0][root] = p
        stack = [(root, p)]
        while stack:
            u, par = stack.pop()
            for v in adj[u]:
                if v != par and depth[v] == -1:
                    depth[v] = d + 1
                    parent[0][v] = u
                    stack.append((v, u))

    # Precompute binary lifting table
