    def get_lca(u, v):
        if depth[u] < depth[v]:
            u, v = v, u

        # Bring u to same depth as v
        diff = depth[u] - depth[v]
        for j in range(LOG):
            if (diff >> j) & 1:
                u = parent[j][u]

        if u == v:
            return u

        for j in range(LOG - 1, -1, -1):
            if parent[j][u] != parent[j][v]:
                u = parent[j][u]
                v = parent[j][v]

        return parent[0][u]

    def dist_tree(u, v):
