    data = input_str.strip().split('\n')
    n, x0, y0 = map(int, data[0].split())
    grid = [list(map(int, row.split())) for row in data[1:n+1]]
    sx, sy = x0 - 1, y0 - 1

    def check_light(x, y, dx, dy):
        for k in range(1, n):
            nx, ny = x + dx * k, y + dy * k
            if 0 <= nx < n and 0 <= ny < n and grid[nx][ny] == 1:
                return True
        return False

    def can_move(x, y, dx, dy):
        if not (0 <= x + dx < n and 0 <= y + dy < n):
            return False
        return check_light(x, y, dx, dy)

    lights = set((i, j) for i in range(n) for j in range(n) if grid[i][j] == 1)

    reachable = set([(sx, sy)])
    q = collections.deque([(sx, sy)])
    while q:
        x, y = q.popleft()
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if (nx, ny) not in reachable and can_move(x, y, dx, dy):
                reachable.add((nx, ny))
                q.append((nx, ny))

    if not lights <= reachable:
        return "NO"

    path = []
    path.append('2' if grid[sx][sy] == 1 else '')

    # BFS path to each light
    for lx, ly in sorted(lights):
        q_path = collections.deque([(sx, sy, "")])
        path_visited = {(sx, sy)}
        found = None

        while q_path and found is None:
            cx, cy, p = q_path.popleft()
            if cx == lx and cy == ly:
                found = p
                break

            for dx, dy, d in [(-1, 0, 'U'), (1, 0, 'D'), (0, -1, 'L'), (0, 1, 'R')]:
                ncx, ncy = cx + dx, cy + dy
                if (ncx, ncy) not in path_visited and can_move(cx, cy, dx, dy):
                    path_visited.add((ncx, ncy))
                    q_path.append((ncx, ncy, p + d))

        if found:
            path.append(found)
            path.append('2')
            grid[lx][ly] = 0

    # Return to start
    q_ret = collections.deque([(sx, sy, "")])
    ret_visited = {(sx, sy)}
    found_ret = None

    def can_move_ret(x, y, dx, dy):
        if not (0 <= x + dx < n and 0 <= y + dy < n):
            return False
        for k in range(1, n):
            nx, ny = x + dx * k, y + dy * k
            if 0 <= nx < n and 0 <= ny < n and grid[nx][ny] == 1:
                return True
        return False

    curr_x, curr_y, curr_path = sx, sy, ""
    curr_vis = {(sx, sy)}
    found_ret = None

    while curr_x != sx or curr_y != sy:
        for dx, dy, d in [(-1, 0, 'U'), (1, 0, 'D'), (0, -1, 'L'), (0, 1, 'R')]:
            if can_move_ret(curr_x, curr_y, dx, dy):
                nx, ny = curr_x + dx, curr_y + dy
                if (nx, ny) not in curr_vis:
                    curr_vis.add((nx, ny))
                    curr_path += d
                    curr_x, curr_y = nx, ny
                    break
        else:
            return "NO"

    path.append(curr_path + "2")

    result = ''.join(path)
    return "YES\n" + result if len(lights) > 0 else "YES\n"
