        """Check if edges i and j cross on the ring"""
        a1, b1 = edges[i]
        a2, b2 = edges[j]
        # Normalize so a < b for both edges
        a1, b1 = min(a1, b1), max(a1, b1)
        a2, b2 = min(a2, b2), max(a2, b2)

        # Count how many endpoints of edge 2 fall in the arc from a1 to b1
        count = 0
        for e in (a2, b2):
            pos = (e - a1) % n
            if 0 < pos < (b1 - a1) % n:
                count += 1
        # If exactly one endpoint is in the arc, edges cross
        return count == 1

    # Build constraint graph where node i is edge i
    # Edge between i and j means they cross and must have different sides
    adj = [[] for _ in range(m)]
    for i in range(m):
        for j in range(i+1, m):
            if cross(i, j):
                adj[i].append(j)
                adj[j].append(i)

    # Check if graph is bipartite (2-colorable)
    color = [-1] * m
    possible = True

    for i in range(m):
        if color[i] == -1:
            color[i] = 0
            stack = [i]
            while stack:
                node = stack.pop()
                for neighbor in adj[node]:
                    if color[neighbor] == -1:
                        color[neighbor] = 1 - color[node]
                        stack.append(neighbor)
                    elif color[neighbor] == color[node]:
                        possible = False
                        return "Impossible"

    # Output 'i' for color 0 (inside), 'o' for color 1 (outside)
    result = []
    for i in range(m):
        if color[i] == 0:
            result.append('i')
        else:
            result.append('o')

