# filename: solution.py

def solution(input_data):
    import sys

    lines = input_data.strip().split('\n')
    n, q = map(int, lines[0].split())
    s0 = lines[1]
    t = lines[2]

    MOD = 10**9 + 7
    queries = []
    for i in range(3, len(lines)):
        parts = lines[i].split()
        queries.append((int(parts[0]), parts[1]))

    # Build small songs that fit in memory
    small = [s0]
    max_len = 2000000
    for i in range(min(n, 20)):
        prev = small[-1]
        new_song = prev + t[i] + prev
        if len(new_song) > max_len:
            break
        small.append(new_song)

    def count_substr(s, w):
        if not s or len(w) > len(s):
            return 0
        cnt = 0
        idx = -1
        while True:
            idx = s.find(w, idx + 1)
            if idx == -1:
                break
            cnt += 1
        return cnt

    def solve(k, w, s0, t, small, memo):
        if (k, w) in memo:
            return memo[(k, w)]

        if k == 0:
            memo[(k, w)] = count_substr(s0, w)
            return memo[(k, w)]

        if k < len(small):
            memo[(k, w)] = count_substr(small[k], w)
            return memo[(k, w)]

        prev = k - 1
        mid = t[prev]
        plen = len(w)

        # Left and right sides are identical
        left = solve(prev, w, s0, t, small, memo)
        right = left

        # Count crossings
        crossing = 0

        if plen == 1:
            if w == mid:
                crossing = 1
        else:
            # Check suffix + mid + prefix = w
            # Iterating over suffixes of s_{prev} followed by mid followed by prefixes of s_{prev}
            # For efficiency, we'll limit searches
            for suffix_len in range(1, min(plen, len(s0) + 1)):
                suffix = s0[-suffix_len:] if suffix_len <= len(s0) else s0[:suffix_len]
                for pre_len in range(0, plen - suffix_len):
                    prefix = s0[:pre_len + 1] if pre_len + 1 <= len(s0) else s0[:pre_len + 1]
                    combined = suffix + mid + prefix[:plen - suffix_len - 1][:pre_len + 1]
                    if combined == w:
                        crossing += 1
        else:
            crossing = 0

        ans = (left + right + crossing) % MOD
        memo[(k, w)] = ans
        return ans

    results = []
    for k, w in queries:
        memo = {}
        results.append(str(solve(k, w, s0, t, small, memo)))

    return '\n'.join(results)
