from collections import deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    first_parts = lines[0].split()
    n, m = int(first_parts[0]), int(first_parts[1])
    swapLR = int(first_parts[2]) if len(first_parts) >= 4 else 0
    swapUD = int(first_parts[3]) if len(first_parts) >= 4 else 0

    grid = lines[1:n+1]

    # Find target 'F' position
    target_r, target_c = -1, -1
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 'F':
                target_r, target_c = r, c

    # Direction mappings - adjusted for swaps
    # If swapLR=1, 'L' moves right and 'R' moves left
    # If swapUD=1, 'U' moves down and 'D' moves up
    moves = {
        'R': (0, 1),
        'L': (0, -1),
        'U': (-1, 0),
        'D': (1, 0)
    }

    if swapLR:
        moves['L'], moves['R'] = moves['R'], moves['L']
    if swapUD:
        moves['U'], moves['D'] = moves['D'], moves['U']

    # BFS to find path from (0,0) to target
    queue = deque([(0, 0, "")])
    visited = {(0, 0)}

    while queue:
        r, c, path = queue.popleft()

        if r == target_r and c == target_c:
            return path

        for move, (dr, dc) in moves.items():
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] != '*':
                if (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc, path + move))

    return ""

