def solution(input_data):
    from itertools import combinations, permutations

    lines = input_data.strip().split('\n')
    m = int(lines[0])

    def is_valid(a, b, is_fifth):
        """Check if set score (a, b) is valid."""
        if a == b:
            return False
        min_score = 15 if is_fifth else 25
        if a > b:
            return a >= min_score and (a - b >= 2)
        else:
            return b >= min_score and (b - a >= 2)

    def get_all_valid_sets():
        """Generate all valid set scores."""
        reg_a = []  # A wins regular set
        reg_b = []  # B wins regular set
        fifth_a = []  # A wins 5th set
        fifth_b = []  # B wins 5th set

        for a in range(1, 40):
            for b in range(1, 40):
                if is_valid(a, b, False):
                    if a > b:
                        reg_a.append((a, b))
                    else:
                        reg_b.append((a, b))

        for a in range(1, 21):
            for b in range(1, 21):
                if is_valid(a, b, True):
                    if a > b:
                        fifth_a.append((a, b))
                    else:
                        fifth_b.append((a, b))

        # Sort: prefer closer scores (more exciting sets)
        reg_a.sort(key=lambda x: -(abs(x[0] - 25) + abs(x[1] - 25)))
        reg_b.sort(key=lambda x: -(abs(x[0] - 25) + abs(x[1] - 25)))
        fifth_a.sort(key=lambda x: -(abs(x[0] - 15) + abs(x[1] - 15)))
        fifth_b.sort(key=lambda x: -(abs(x[0] - 15) + abs(x[1] - 15)))

        return reg_a, reg_b, fifth_a, fifth_b

    def solve_match(a_total, b_total):
        """Find best match result for given total points."""
        reg_a, reg_b, fifth_a, fifth_b = get_all_valid_sets()

        # Try match results in priority order
        results_configs = [
            (3, 0, 3, reg_a),      # A wins all
            (3, 1, 4, reg_a),      # A wins 3, B wins 1
            (3, 2, 5, fifth_a),    # A wins 3, B wins 2, goes to 5th
            (2, 3, 5, fifth_a),    # B wins 3, A wins 2, goes to 5th
            (1, 3, 4, reg_a),      # A wins 1, B wins 3
            (0, 3, 3, reg_b)       # B wins all
        ]

        for aw, bw, total_sets, win_candidates in results_configs:
            if aw + bw > 5 or aw + bw == 0:
                continue

            # Find if this configuration is valid
            valid_seq = find_sequence(aw, bw, total_sets, a_total, b_total, reg_a, reg_b, fifth_a, fifth_b)
            if valid_seq:
                return f"{aw}:{bw}\n" + " ".join([f"{s[0]}:{s[1]}" for s in valid_seq])

        return "Impossible"

    def find_sequence(aw, bw, total_sets, a_target, b_target, reg_a, reg_b, fifth_a, fifth_b):
        """Find valid sequence of set scores."""

        # Generate sequences where A wins exactly 'aw' sets
        from itertools import combinations
        win_positions = list(combinations(range(total_sets), aw))

        for pos in win_positions:
            seq = ['A' if i in pos else 'B' for i in range(total_sets)]
            path = search_sequence(0, a_target, b_target, seq, reg_a, reg_b, fifth_a, fifth_b)
            if path:
                return path

        return None

    def search_sequence(idx, a_remaining, b_remaining, seq, reg_a, reg_b, fifth_a, fifth_b):
        """Recursively find valid set scores."""
        if a_remaining < 0 or b_remaining < 0:
            return None

        if idx == len(seq):
            return [] if a_remaining == 0 and b_remaining == 0 else None

        turn = seq[idx]
        score_set = reg_a if turn == 'A' else reg_b

        # Sample from candidates (try closer scores first)
        candidates = score_set[:30] if idx < 4 else (fifth_a if turn == 'A' else fifth_b)[:30]

        for sc in candidates:
            if a_remaining >= sc[0] and b_remaining >= sc[1]:
                result = search_sequence(idx + 1, 
                                         a_remaining - sc[0],
                                         b_remaining - sc[1],
                                         seq, reg_a, reg_b, fifth_a, fifth_b)
                if result:
                    return [sc] + result

        return None

    results = []
    for i in range(1, m + 1):
        a, b = map(int, lines[i].split())
        results.append(solve_match(a, b))

    return "\n".join(results)
